entries[44141] = { ["name"] = "Saat der Verderbnis", ["text"] = "550 Mana 30 Meter Reichweite\nWirken in 2 sek.\nPflanzt dem feindlichen Ziel eine Saat der Verderbnis ein, die im Verlauf von 18 sec 1500 Schattenschaden verursacht. Wenn das Ziel insgesamt 2500 Schaden erleidet, detoniert die Saat und fügt allen Feinden im Umkreis von 10 Metern um das Ziel Schattenschaden zu." }
entries[44142] = { ["name"] = "Todesmantel", ["text"] = "200 Mana 30 Meter Reichweite\nSofort\nVerursacht 500 Schattenschaden und das betroffene Ziel läuft 3 sec lang voller Entsetzen davon. Der Zaubernde erhält 100% des verursachten Schadens in Gesundheit." }
