entries[44148] = { ["name"] = "Flammende Reflexion", ["text"] = "60 Meter Reichweite\nSofort\nBeschwört Feuerbälle im gewählten Gebiet. Die Feuerbälle werden explodieren und 850 Feuerschaden zufügen, sollte ihnen jemand zu nahe kommen." }
