entries[44151] = { ["name"] = "Turbogetriebene Flugmaschine", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine turbogetriebene Flugmaschine oder gibt sie frei. Das ist ein sehr schneller Flugapparat. Die Nutzung benötigt eine Ingenieurskunstfertigkeit von 375." }
