entries[44153] = { ["name"] = "Flugmaschine", ["text"] = "Wirken in 1.5 sek.\nBeschwört eine Flugmaschine oder gibt sie frei. Diese Maschine kann nur in der Scherbenwelt und in Nordend verwendet werden. Die Nutzung benötigt eine Ingenieurskunstfertigkeit von 300." }
